import crypto from 'crypto'
import { db, sqliteDb } from '@/db/index.js'
import type Database from 'better-sqlite3'
import { sales, saleLineItems, payments, vatRates, paymentAllocations, stockMovements, sequences } from '@/db/schema.js'
import { desc, eq, inArray, sql, sum, asc } from 'drizzle-orm'
import { createDirectSaleInputSchema } from '@pi-skeleton/shared/validations/sales'
import { computeLineTotals } from '@shared/lib/pricing.js'

// ============================================================================
// Types
// ============================================================================

/** Input for creating a direct sale (validated via Zod schema) */
export interface CreateDirectSaleInput {
  /** Optional customer ID — null/absent means walk-in */
  customerId?: string | null
  /** Payment method */
  paymentMethod: 'cash' | 'card'
  /** Line items being purchased */
  lineItems: Array<{
    partId: string
    quantity: number
    unitPriceNet: number
    vatRateId: string
    description: string
    discountPercent?: number | null
  }>
}

/** Result returned after a successful sale creation */
export interface SaleResult {
  /** The created sale header */
  sale: typeof sales.$inferSelect
  /** The created payment record */
  payment: typeof payments.$inferSelect
  /** All line items for this sale */
  lineItems: typeof saleLineItems.$inferSelect[]
}

/** Error thrown when stock validation fails */
export class InsufficientStockError extends Error {
  constructor(public readonly shortfalls: Array<{ partId: string; requested: number; available: number }>) {
    super(`Insufficient stock for ${shortfalls.length} part(s)`)
    this.name = 'InsufficientStockError'
  }
}

/** Error thrown when a sale is not found */
export class SaleNotFoundError extends Error {
  constructor(public readonly id: string) {
    super(`Sale not found: ${id}`)
    this.name = 'SaleNotFoundError'
  }
}

// ============================================================================
// Stock validation — aggregates from stock_movements (no denormalized trust)
// ============================================================================

/** Input: one part with a requested quantity to validate. */
interface StockCheckRequest {
  /** Part ID to check availability for */
  partId: string
  /** Number of units the caller wants to sell */
  requestedQuantity: number
}

/** One part that does not have enough stock. */
interface ShortfallDetail {
  /** The part ID with insufficient stock */
  partId: string
  /** How many units were requested */
  requested: number
  /** How many units are actually available (computed from movements) */
  available: number
}

/** Result of validating a batch of stock requests. */
interface StockValidationResult {
  /** true if every part has sufficient stock; false otherwise */
  valid: boolean
  /** Non-empty only when valid is false — lists each short-falling part */
  shortfalls: ShortfallDetail[]
}

/**
 * Validate whether requested quantities are available in stock.
 *
 * Computes available stock per part by summing `quantityDelta` from the
 * `stock_movements` table — never trusts denormalized `quantityOnHand`.
 */
async function validateStockAvailability(
  requests: StockCheckRequest[]
): Promise<StockValidationResult> {
  if (requests.length === 0) {
    return { valid: true, shortfalls: [] }
  }

  const partIds = [...new Set(requests.map(r => r.partId))]

  const aggregationQuery = db
    .select({
      partId: stockMovements.partId,
      totalDelta: sql<number>`COALESCE(${sum(stockMovements.quantityDelta)}, 0)`
    })
    .from(stockMovements)
    .where(inArray(stockMovements.partId, partIds))
    .groupBy(stockMovements.partId)

  const aggregationResults = await aggregationQuery

  const availableMap = new Map<string, number>()
  for (const row of aggregationResults) {
    availableMap.set(row.partId, Number(row.totalDelta))
  }

  const shortfalls: ShortfallDetail[] = []
  for (const req of requests) {
    const available = availableMap.get(req.partId) ?? 0
    if (req.requestedQuantity > available) {
      shortfalls.push({
        partId: req.partId,
        requested: req.requestedQuantity,
        available
      })
    }
  }

  shortfalls.sort((a, b) => a.partId.localeCompare(b.partId))

  return {
    valid: shortfalls.length === 0,
    shortfalls
  }
}

// ============================================================================
// Sequence helper — atomic increment for document numbering
// ============================================================================

/**
 * Get the next sequential value for a document number sequence.
 * Atomically increments the counter and returns the new value.
 */
async function getNextValue(name: string): Promise<number> {
  const updateResult = await db
    .update(sequences)
    .set({ currentValue: sql`${sequences.currentValue} + 1` })
    .where(eq(sequences.name, name))

  if (updateResult.changes === 0) {
    await db.insert(sequences).values({ name, currentValue: 1 })
    return 1
  }

  const [row] = await db
    .select({ currentValue: sequences.currentValue })
    .from(sequences)
    .where(eq(sequences.name, name))

  return row!.currentValue
}

// ============================================================================
// Public API
// ============================================================================

/**
 * Create a direct sale atomically in a single database transaction.
 *
 * Flow: validate input → check stock → get sequence number → insert sale header
 *       → insert line items → insert payment → insert allocation → insert stock movements
 * All-or-nothing: any failure rolls back everything.
 *
 * @param rawInput — Unvalidated input object (will be validated via Zod)
 * @returns Sale result with created entities
 */
export async function createDirectSale(rawInput: unknown): Promise<SaleResult> {
  // Validate input via Zod schema
  const parsed = createDirectSaleInputSchema.safeParse(rawInput)
  if (!parsed.success) {
    throw new Error(`Invalid sale input: ${parsed.error.message}`)
  }

  const input = parsed.data as CreateDirectSaleInput

  // ---------------------------------------------------------------------------
  // Step 1: Validate stock availability for all line items
  // ---------------------------------------------------------------------------
  const stockRequests = input.lineItems.map((item) => ({
    partId: item.partId,
    requestedQuantity: item.quantity
  }))

  const stockResult = await validateStockAvailability(stockRequests)
  if (!stockResult.valid) {
    throw new InsufficientStockError(stockResult.shortfalls)
  }

  // ---------------------------------------------------------------------------
  // Step 2: Get sale number from sequence table (atomic increment)
  // ---------------------------------------------------------------------------
  const saleNumberSeq = await getNextValue('sale')
  const saleNumber = `SA-${String(saleNumberSeq).padStart(4, '0')}`

  // ---------------------------------------------------------------------------
  // Step 3: Fetch VAT rates needed for line item calculations
  // ---------------------------------------------------------------------------
  const allVatRates = await db.select({ id: vatRates.id, rate: vatRates.rate }).from(vatRates)
  const vatRatesMap = new Map<string, number>()
  for (const row of allVatRates) {
    vatRatesMap.set(row.id, Number(row.rate))
  }

  // ---------------------------------------------------------------------------
  // Step 4: Compute line item totals using shared pricing lib
  // ---------------------------------------------------------------------------
  const lineItemsData = input.lineItems.map((item) => {
    const vatRateBps = vatRatesMap.get(item.vatRateId) ?? 0
    const totals = computeLineTotals(item.unitPriceNet, item.quantity, item.discountPercent, vatRateBps)

    return {
      partId: item.partId,
      quantity: item.quantity,
      unitPriceNet: item.unitPriceNet,
      vatRateId: item.vatRateId,
      description: item.description,
      discountPercent: item.discountPercent ?? null,
      lineTotalNet: totals.net,
      lineTotalVat: totals.vat,
      lineTotalGross: totals.gross,
      lineType: 'part' as const
    }
  })

  const subtotalNet = lineItemsData.reduce((sum, item) => sum + item.lineTotalNet, 0)
  const vatTotal = lineItemsData.reduce((sum, item) => sum + item.lineTotalVat, 0)
  const totalGross = subtotalNet + vatTotal

  // ---------------------------------------------------------------------------
  // Step 5: Execute single transaction — all inserts or nothing
  // ---------------------------------------------------------------------------
  const saleId = crypto.randomUUID()
  const paymentId = crypto.randomUUID()

  const client = sqliteDb as Database.Database
  const run = (sqlStr: string, params?: unknown[]) => {
    return client.prepare(sqlStr).run(...(params ?? []))
  }

  try {
    // Begin transaction
    run('BEGIN TRANSACTION')

    // Insert sale header
    run(
      'INSERT INTO sales (id, sale_number, customer_id, source_type, source_id, status, subtotal_net, vat_total, total_gross, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
      [saleId, saleNumber, input.customerId ?? null, 'direct_sale', null, 'completed', subtotalNet, vatTotal, totalGross, Date.now()]
    )

    const now = Date.now()

    // Insert line items
    for (const item of lineItemsData) {
      const lineItemId = crypto.randomUUID()
      run(
        'INSERT INTO sale_line_items (id, sale_id, line_type, part_id, description, quantity, unit_price_net, vat_rate_id, discount_percent, line_total_net, line_total_vat, line_total_gross, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
        [lineItemId, saleId, item.lineType, item.partId, item.description, item.quantity, item.unitPriceNet, item.vatRateId, item.discountPercent, item.lineTotalNet, item.lineTotalVat, item.lineTotalGross, now]
      )
    }

    // Insert payment record
    run(
      'INSERT INTO payments (id, method, amount, created_at) VALUES (?, ?, ?, ?)',
      [paymentId, input.paymentMethod, totalGross, now]
    )

    // Insert payment allocation (payment → sale)
    run(
      'INSERT INTO payment_allocations (id, payment_id, target_type, target_id, allocated_amount) VALUES (?, ?, ?, ?, ?)',
      [crypto.randomUUID(), paymentId, 'sale', saleId, totalGross]
    )

    // Insert stock movements (negative deltas for each part sold)
    for (const item of input.lineItems) {
      run(
        'INSERT INTO stock_movements (id, part_id, quantity_delta, reason, reference_type, reference_id, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)',
        [crypto.randomUUID(), item.partId, -item.quantity, 'sale', 'sale', saleId, now]
      )
    }

    // Commit transaction
    run('COMMIT')
  } catch (err) {
    // Rollback on any error
    try { run('ROLLBACK') }
    catch {}
    throw err
  }

  // ---------------------------------------------------------------------------
  // Step 6: Fetch and return created entities
  // ---------------------------------------------------------------------------
  const [createdSale] = await db.select().from(sales).where(eq(sales.id, saleId))
  const [createdPayment] = await db.select().from(payments).where(eq(payments.id, paymentId))
  const lineItemRows = await db.select().from(saleLineItems).orderBy(saleLineItems.createdAt)

  return {
    sale: createdSale!,
    payment: createdPayment!,
    lineItems: lineItemRows
  }
}

/**
 * Void a completed sale by setting its status to 'voided'.
 *
 * Does NOT reverse stock movements (per domain rule R13 — voiding accepts error risk).
 * Guards against voiding already-voided sales.
 *
 * @param saleId — ID of the sale to void
 * @returns The updated sale record
 */
export async function voidSale(saleId: string): Promise<typeof sales.$inferSelect> {
  // Check if sale exists and is not already voided
  const existing = await db.select().from(sales).where(eq(sales.id, saleId))

  if (existing.length === 0) {
    throw new SaleNotFoundError(saleId)
  }

  if (existing[0].status === 'voided') {
    throw new Error(`Sale ${saleId} is already voided`)
  }

  // Update status to voided
  const [updated] = await db
    .update(sales)
    .set({ status: 'voided' })
    .where(eq(sales.id, saleId))
    .returning()

  return updated!
}

/**
 * Find a single sale by ID.
 */
export async function findSaleById(id: string) {
  const [result] = await db.select().from(sales).where(eq(sales.id, id))
  return result ?? undefined
}

/**
 * List recent sales ordered by creation date (newest first).
 *
 * @param limit — Maximum number of rows to return (default: 50)
 * @returns Array of sale records sorted newest-first
 */
export async function listSales(limit = 50) {
  return db
    .select()
    .from(sales)
    .orderBy(desc(sales.createdAt))
    .limit(limit)
}

/**
 * Get all line items for a sale, ordered by creation.
 */
export async function findLineItemsBySaleId(saleId: string) {
  return db.select().from(saleLineItems).where(eq(saleLineItems.saleId, saleId)).orderBy(asc(saleLineItems.createdAt))
}

/**
 * Get all payments for a sale (via allocations), ordered by creation.
 */
export async function findPaymentsBySaleId(saleId: string) {
  const allocations = await db.select().from(paymentAllocations).where(eq(paymentAllocations.targetId, saleId))
  if (allocations.length === 0) return []

  const paymentIds = allocations.map(a => a.paymentId)
  return db.select().from(payments).where(sql`${payments.id} IN (${sql.join(paymentIds)})`).orderBy(asc(payments.createdAt))
}

/**
 * Get all stock movements referencing a specific sale.
 */
export async function findMovementsBySaleId(saleId: string) {
  return db.select().from(stockMovements).where(eq(stockMovements.referenceId, saleId))
}

import { useState } from 'react'
import type { PaymentMethod as PaymentMethodType } from '@shared/validations'
import * as DialogPrimitive from '@radix-ui/react-dialog'
import { X } from 'lucide-react'
import { cn } from '@/shared/lib/utils'
import { Button } from '@/components/ui/button'
import { Label } from '@/components/ui/label'
import { useCartStore } from '../store'

// ============================================================================
// Component — Payment Dialog (Radix Dialog wrapper)
// ============================================================================

// ============================================================================
// Types
// ============================================================================

export interface PaymentDialogProps {
  open: boolean
  onClose: () => void
  onCheckout: (method: PaymentMethodType) => Promise<void>
}

// ============================================================================
// Component — Payment Dialog
// ============================================================================

export function PaymentDialog({ open, onClose, onCheckout }: PaymentDialogProps) {
  const totalGross = useCartStore((s) => s.totalGross)
  const canCheckout = useCartStore((s) => s.canCheckout)
  const checkoutSuccess = useCartStore((s) => s.checkoutSuccess)
  const clearErrors = useCartStore((s) => s.clearErrors)

  const [selectedMethod, setSelectedMethod] = useState<PaymentMethodType>('cash')
  const [isSubmitting, setIsSubmitting] = useState(false)

  const paymentMethods: Array<{ value: PaymentMethodType; label: string }> = [
    { value: 'cash', label: '💵 Cash' },
    { value: 'card', label: '💳 Card' },
  ]

  const handleCheckout = async () => {
    if (!canCheckout || isSubmitting) return
    setIsSubmitting(true)
    try {
      await onCheckout(selectedMethod)
    } finally {
      setIsSubmitting(false)
    }
  }

  // When success state appears, close the dialog after a brief delay
  const isSuccess = !!checkoutSuccess
  if (isSuccess && open) {
    // Use setTimeout to allow the success message to render before closing
    setTimeout(() => {
      clearErrors()
      onClose()
    }, 1500)
  }

  return (
    <DialogPrimitive.Root open={open} onOpenChange={(isOpen) => !isOpen && onClose()}>
      <DialogPrimitive.Portal>
        <DialogPrimitive.Overlay className="fixed inset-0 z-50 bg-black/80 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0" />
        <DialogPrimitive.Content
          className={cn(
            'fixed left-[50%] top-[50%] z-50 w-full max-w-md translate-x-[-50%] translate-y-[-50%] gap-4 border bg-background p-6 shadow-lg duration-200 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[state=closed]:slide-out-to-left-1/2 data-[state=closed]:slide-out-to-top-[48%] data-[state=open]:slide-in-from-left-1/2 data-[state=open]:slide-in-from-top-[48%] sm:rounded-lg'
          )}
        >
          {/* Close button */}
          <DialogPrimitive.Close className="absolute right-4 top-4 rounded-sm opacity-70 ring-offset-background transition-opacity hover:opacity-100 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 disabled:pointer-events-none data-[state=open]:bg-accent data-[state=open]:text-muted-foreground">
            <X className="h-4 w-4" />
            <span className="sr-only">Close</span>
          </DialogPrimitive.Close>

          {/* Dialog title + description */}
          <div className="flex flex-col gap-1.5">
            <DialogPrimitive.Title className="text-lg font-semibold leading-none tracking-tight">
              Checkout
            </DialogPrimitive.Title>
            <DialogPrimitive.Description className="text-sm text-muted-foreground">
              Select payment method and complete the sale
            </DialogPrimitive.Description>
          </div>

          {/* Dialog content */}
          <div className="space-y-4">
            {/* Total display */}
            <div className="text-center p-3 bg-accent rounded-md">
              <div className="text-sm text-muted-foreground mb-1">Total Due</div>
              <div className="text-2xl font-bold font-mono">{formatPrice(totalGross)}</div>
            </div>

            {/* Payment method selector */}
            <div className="space-y-2">
              <Label className="text-sm font-medium text-muted-foreground">Payment Method</Label>
              <div className="grid grid-cols-2 gap-2">
                {paymentMethods.map((method) => (
                  <Button
                    key={method.value}
                    variant={selectedMethod === method.value ? 'default' : 'outline'}
                    size="sm"
                    onClick={() => setSelectedMethod(method.value)}
                    disabled={isSubmitting}
                    className={cn('justify-start', selectedMethod === method.value && 'border-dashed')}
                  >
                    {method.label}
                  </Button>
                ))}
              </div>
            </div>

            {/* Checkout button */}
            <Button
              onClick={handleCheckout}
              disabled={!canCheckout || isSubmitting}
              className="w-full"
              size="lg"
            >
              {isSubmitting
                ? 'Processing...'
                : canCheckout
                  ? `Complete Sale — ${formatPrice(totalGross)}`
                  : 'Cart is empty'}
            </Button>

            {/* Success/Error display */}
            <CheckoutStatusDisplay />
          </div>
        </DialogPrimitive.Content>
      </DialogPrimitive.Portal>
    </DialogPrimitive.Root>
  )
}

// ============================================================================
// Sub-component — Checkout Status Display (Success / Error)
// ============================================================================

function CheckoutStatusDisplay() {
  const checkoutError = useCartStore((s) => s.checkoutError)
  const checkoutSuccess = useCartStore((s) => s.checkoutSuccess)
  const clearErrors = useCartStore((s) => s.clearErrors)

  if (checkoutSuccess) {
    return (
      <div className="p-3 bg-green-50 border border-green-200 rounded-md text-center space-y-1">
        <div className="text-sm font-semibold text-green-800">✓ Sale Complete</div>
        <div className="text-xs text-green-700">Receipt: {checkoutSuccess.saleNumber}</div>
      </div>
    )
  }

  if (checkoutError) {
    return (
      <div className="p-3 bg-red-50 border border-red-200 rounded-md text-center space-y-1">
        <div className="text-sm font-semibold text-red-800">✕ Checkout Failed</div>
        <div className="text-xs text-red-700">{checkoutError}</div>
        <Button variant="ghost" size="sm" onClick={clearErrors} className="text-xs h-6">
          Dismiss
        </Button>
      </div>
    )
  }

  return null
}

// ============================================================================
// Helpers
// ============================================================================

function formatPrice(cents: number): string {
  const euros = (cents / 100).toFixed(2)
  return `€${euros}`
}

import { Hono } from 'hono'
import {
  createDirectSale,
  voidSale,
  type SaleResult,
  InsufficientStockError,
  SaleNotFoundError,
  listSales,
  findSaleById,
  findLineItemsBySaleId,
  findPaymentsBySaleId,
  findMovementsBySaleId
} from '../services/sale.service.js'

const salesRoutes = new Hono()

// ============================================================================
// POST /sales — Create a direct sale
// ============================================================================

/**
 * Error response shape.
 */
interface ErrorResponse {
  error: string
  code?: string
  shortfalls?: Array<{ partId: string; requested: number; available: number }>
}

salesRoutes.post('/', async (c) => {
  try {
    const rawInput = await c.req.json()

    const result: SaleResult = await createDirectSale(rawInput)

    return c.json(
      {
        sale: Object.fromEntries(Object.entries(result.sale)),
        payment: Object.fromEntries(Object.entries(result.payment)),
        lineItems: result.lineItems.map(item => Object.fromEntries(Object.entries(item)))
      },
      201
    )
  } catch (err) {
    if (err instanceof InsufficientStockError) {
      return c.json(
        {
          error: 'Insufficient stock',
          code: 'INSUFFICIENT_STOCK',
          shortfalls: err.shortfalls
        } as ErrorResponse,
        409
      )
    }

    if (err instanceof Error && err.message.startsWith('Invalid sale input')) {
      return c.json(
        { error: err.message, code: 'VALIDATION_ERROR' } as ErrorResponse,
        400
      )
    }

    console.error('[POST /sales] Unexpected error:', err)
    return c.json(
      { error: 'Internal server error', code: 'INTERNAL_ERROR' },
      500
    )
  }
})

// ============================================================================
// GET /sales — List recent sales history
// ============================================================================

interface SalesListResponse {
  /** Array of sale records (newest first) */
  sales: Record<string, unknown>[]
  /** Total count of all sales */
  total: number
}

salesRoutes.get('/', async (c) => {
  const limit = Math.min(parseInt(c.req.query('limit') ?? '50', 10) || 50, 200)

  const saleRows = await listSales(limit)
  const total = await listSales(999999).then(rows => rows.length)

  return c.json({
    sales: saleRows.map(row => Object.fromEntries(Object.entries(row))),
    total
  } as SalesListResponse)
})

// ============================================================================
// GET /sales/:id — Get a single sale with full details
// ============================================================================

interface SaleDetailResponse {
  /** The sale header */
  sale: Record<string, unknown>
  /** Line items for this sale */
  lineItems: Record<string, unknown>[]
  /** Payments allocated to this sale */
  payments: Record<string, unknown>[]
  /** Stock movements referencing this sale */
  stockMovements: Record<string, unknown>[]
}

salesRoutes.get('/:id', async (c) => {
  const id = c.req.param('id')

  const sale = await findSaleById(id)
  if (!sale) {
    return c.json({ error: 'Sale not found', code: 'NOT_FOUND' }, 404)
  }

  const [lineItems, payments, stockMovements] = await Promise.all([
    findLineItemsBySaleId(id),
    findPaymentsBySaleId(id),
    findMovementsBySaleId(id)
  ])

  return c.json({
    sale: Object.fromEntries(Object.entries(sale)),
    lineItems: lineItems.map(item => Object.fromEntries(Object.entries(item))),
    payments: payments.map(payment => Object.fromEntries(Object.entries(payment))),
    stockMovements: stockMovements.map(mvmt => Object.fromEntries(Object.entries(mvmt)))
  } as SaleDetailResponse)
})

// ============================================================================
// PATCH /sales/:id/void — Void a completed sale
// ============================================================================

salesRoutes.patch('/:id/void', async (c) => {
  const id = c.req.param('id')

  try {
    const updatedSale = await voidSale(id)

    return c.json({
      sale: Object.fromEntries(Object.entries(updatedSale))
    })
  } catch (err) {
    if (err instanceof SaleNotFoundError) {
      return c.json(
        { error: 'Sale not found', code: 'NOT_FOUND' },
        404
      )
    }

    if (err instanceof Error && err.message.includes('already voided')) {
      return c.json(
        { error: err.message, code: 'ALREADY_VOIDED' },
        409
      )
    }

    console.error('[PATCH /sales/:id/void] Unexpected error:', err)
    return c.json(
      { error: 'Internal server error', code: 'INTERNAL_ERROR' },
      500
    )
  }
})

export default salesRoutes

/**
 * Pure functions for line item price calculations.
 *
 * All amounts in cents (integer). Discount and VAT rates are in basis points
 * (100 = 1%, 2100 = 21%). No framework dependencies — importable from both
 * client and server.
 *
 * This is the single source of truth for line math, replacing duplicated
 * implementations in client store and server service.
 */

// ============================================================================
// Line Item Math
// ============================================================================

/**
 * Compute line item totals from quantity, unit price, discount, and VAT rate.
 *
 * Formula: discountedNetPerUnit = unitPriceNet × (1 - discountBps / 10000)
 *          lineNetTotal = discountedNetPerUnit × quantity
 *          lineVatTotal = round(lineNetTotal × vatRateBps / 10000)
 *          lineGrossTotal = lineNetTotal + lineVatTotal
 *
 * @param unitPriceNet — Ex-tax price per unit in cents (integer)
 * @param quantity — Number of units (integer, >= 1)
 * @param discountPercentBps — Discount in basis points (null or 0 = no discount). e.g. 1000 = 10%
 * @param vatRateBps — VAT rate in basis points. e.g. 2100 = 21%, 600 = 6%
 * @returns Object with net, vat, and gross totals in cents (integer)
 */
export function computeLineTotals(
  unitPriceNet: number,
  quantity: number,
  discountPercentBps: number | null | undefined,
  vatRateBps: number
): { net: number; vat: number; gross: number } {
  // Apply discount (basis points → fraction)
  const discountFactor = discountPercentBps ? 1 - discountPercentBps / 10000 : 1
  const discountedNetPerUnit = Math.round(unitPriceNet * discountFactor)
  const lineNetTotal = discountedNetPerUnit * quantity

  // Compute VAT (round to nearest cent)
  const lineVatTotal = Math.round(lineNetTotal * vatRateBps / 10000)

  return {
    net: lineNetTotal,
    vat: lineVatTotal,
    gross: lineNetTotal + lineVatTotal
  }
}

import { z } from 'zod'

/** Payment method accepted at checkout */
export const paymentMethodSchema = z.enum(['cash', 'card'])

export type PaymentMethod = z.infer<typeof paymentMethodSchema>

/** A single line item in a sale cart / creation request */
export const cartLineItemSchema = z.object({
  /** Part ID to sell */
  partId: z.string().min(1, 'partId is required'),
  /** Number of units to sell (must be positive) */
  quantity: z.number().int().positive('quantity must be a positive integer'),
  /** Net unit price in cents (snapshot at time of sale) */
  unitPriceNet: z.number().int().nonnegative('unitPriceNet must be non-negative'),
  /** VAT rate ID — references vatRates table */
  vatRateId: z.string().min(1, 'vatRateId is required'),
  /** Human-readable description (snapshot at time of sale) */
  description: z.string().min(1, 'description is required').max(500),
  /** Discount in basis points — null means no discount */
  discountPercent: z.number().int().nonnegative().nullable().optional(),
})

export type CartLineItem = z.infer<typeof cartLineItemSchema>

/** Full input for creating a direct sale at checkout */
export const createDirectSaleInputSchema = z.object({
  /** Optional customer ID — null/absent means walk-in */
  customerId: z.string().nullable().optional(),
  /** Payment method for the full amount */
  paymentMethod: paymentMethodSchema,
  /** Line items being purchased */
  lineItems: z.array(cartLineItemSchema).min(1, 'At least one line item is required'),
})

