import { z } from 'zod'
import { paymentMethodSchema } from './sales.js'

/** Line item for a customer order — supports parts, labor, and bicycles */
export const customerOrderLineItemSchema = z.object({
  lineType: z.enum(['part', 'labor', 'bicycle']),
  partId: z.string().nullable().optional(),
  laborServiceId: z.string().nullable().optional(),
  description: z.string().min(1, 'description is required').max(500),
  quantity: z.number().int().positive('quantity must be a positive integer'),
  unitPriceNet: z.number().int().nonnegative('unitPriceNet must be non-negative'),
  vatRateId: z.string().min(1, 'vatRateId is required'),
  discountPercent: z.number().int().nonnegative().nullable().optional(),
  // Bicycle-specific fields (only used when lineType='bicycle')
  bicycleId: z.string().nullable().optional(),
  bicycleBrand: z.string().nullable().optional(),
  bicycleModel: z.string().nullable().optional(),
  bicycleYear: z.number().int().nullable().optional(),
  bicycleColor: z.string().nullable().optional(),
  bicycleFrameSize: z.string().nullable().optional(),
})

export type CustomerOrderLineItem = z.infer<typeof customerOrderLineItemSchema>

/** Input for creating a customer order with optional deposit */
export const createCustomerOrderInputSchema = z.object({
  customerId: z.string().min(1, 'customerId is required'),
  lineItems: z.array(customerOrderLineItemSchema).min(1, 'At least one line item is required'),
  depositAmount: z.number().int().nonnegative('depositAmount must be non-negative').nullable().optional(),
  paymentMethod: paymentMethodSchema.nullable().optional(),
  expectedDeliveryDate: z.string().datetime().nullable().optional(),
  internalNotes: z.string().max(2000).nullable().optional(),
}).refine(
  (data) => {
    // If depositAmount > 0, paymentMethod must be provided
    if ((data.depositAmount ?? 0) > 0 && !data.paymentMethod) {
      return false
    }
    return true
  },
  { message: 'paymentMethod is required when depositAmount > 0', path: ['paymentMethod'] }
)

export type CreateCustomerOrderInput = z.infer<typeof createCustomerOrderInputSchema>

/** Customer order status */
export const customerOrderStatusSchema = z.enum(['pending', 'ordered', 'ready', 'fulfilled', 'cancelled'])
export type CustomerOrderStatus = z.infer<typeof customerOrderStatusSchema>

import { describe, it, expect, beforeEach } from 'vitest'
import { db } from '@/db/index.js'
import { customerOrders, customerOrderLineItems, payments, paymentAllocations, sequences, vatRates, bicycles } from '@/db/schema.js'
import { eq } from 'drizzle-orm'

// Import service functions (will be created in GREEN phase)
// import { createCustomerOrder, listCustomerOrders, findCustomerOrderByCustomerId } from '../customer-order.service.js'

describe('Customer Order Service — Integration Tests', () => {
  async function resetTables() {
    await db.delete(paymentAllocations)
    await db.delete(payments)
    await db.delete(customerOrderLineItems)
    await db.delete(customerOrders)
    // Reset sequences for customer_orders if it exists
    try {
      await db.delete(sequences).where(eq(sequences.name, 'customer_order'))
    } catch {}
  }

  beforeEach(async () => {
    await resetTables()
  })

  describe('createCustomerOrder', () => {
    // ---------------------------------------------------------------------------
    // TRACER BULLET: Create order without deposit — basic happy path
    // ---------------------------------------------------------------------------
    it('should create a customer order with line items and sequential order number (tracer bullet)', async () => {
      const { createCustomerOrder } = await import('../customer-order.service.js')

      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })

      const input = {
        customerId: 'cust-abc-123',
        lineItems: [
          {
            lineType: 'part' as const,
            partId: 'p1',
            description: 'Bearing 6205',
            quantity: 2,
            unitPriceNet: 1000,
            vatRateId: 'vat-standard',
          },
          {
            lineType: 'labor' as const,
            laborServiceId: 'ls-1',
            description: 'Installation',
            quantity: 1,
            unitPriceNet: 5000,
            vatRateId: 'vat-standard',
          },
        ],
      }

      const result = await createCustomerOrder(input)

      // Verify order header
      expect(result.order).toBeDefined()
      expect(result.order.customerId).toBe('cust-abc-123')
      expect(result.order.status).toBe('pending')
      expect(result.order.orderNumber).toMatch(/^CO-\d{4}$/)

      // totalPriceNet = 2*1000 + 1*5000 = 7000
      expect(result.order.totalPriceNet).toBe(7000)

      // Verify line items created
      expect(result.lineItems).toHaveLength(2)
      expect(result.lineItems[0].lineType).toBe('part')
      expect(result.lineItems[1].lineType).toBe('labor')

      // No payment or allocation when no deposit
      expect(result.payment).toBeUndefined()
      expect(result.allocation).toBeUndefined()
    })

    // ---------------------------------------------------------------------------
    // Create order with deposit — creates payment + allocation atomically
    // ---------------------------------------------------------------------------
    it('should create a customer order with deposit payment and allocation', async () => {
      const { createCustomerOrder } = await import('../customer-order.service.js')

      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })

      const input = {
        customerId: 'cust-abc-123',
        lineItems: [
          {
            lineType: 'part' as const,
            partId: 'p1',
            description: 'Bearing 6205',
            quantity: 1,
            unitPriceNet: 1000,
            vatRateId: 'vat-standard',
          },
        ],
        depositAmount: 500, // 5.00 EUR deposit
        paymentMethod: 'card' as const,
      }

      const result = await createCustomerOrder(input)

      // Order created
      expect(result.order).toBeDefined()
      expect(result.order.totalPriceNet).toBe(1000)

      // Payment record created with deposit amount
      expect(result.payment).toBeDefined()
      expect(result.payment!.amount).toBe(500)
      expect(result.payment!.method).toBe('card')

      // Allocation links payment to customer order
      expect(result.allocation).toBeDefined()
      expect(result.allocation!.targetType).toBe('customer_order')
      expect(result.allocation!.targetId).toBe(result.order.id)
      expect(result.allocation!.allocatedAmount).toBe(500)
    })

    // ---------------------------------------------------------------------------
    // Reject deposit when order contains leased bicycle line items
    // ---------------------------------------------------------------------------
    it('should reject deposit collection when order contains a leased bicycle', async () => {
      const { createCustomerOrder, LeasedBicycleDepositError } = await import('../customer-order.service.js')

      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })
      // Insert a bicycle with isLease=true
      await db.insert(bicycles).values({
        id: 'bike-lease-1',
        source: 'inventory' as const,
        brand: 'Trek',
        model: 'Domane',
        isLease: true,
        status: 'inventory' as const,
      })

      const input = {
        customerId: 'cust-abc-123',
        lineItems: [
          {
            lineType: 'bicycle' as const,
            bicycleId: 'bike-lease-1',
            description: 'Trek Domane (leased)',
            quantity: 1,
            unitPriceNet: 50000,
            vatRateId: 'vat-standard',
          },
        ],
        depositAmount: 2500,
        paymentMethod: 'cash' as const,
      }

      await expect(createCustomerOrder(input)).rejects.toThrow(LeasedBicycleDepositError)
    })

    // ---------------------------------------------------------------------------
    // Reject missing customerId (no anonymous orders)
    // ---------------------------------------------------------------------------
    it('should reject order creation when customerId is missing', async () => {
      const { createCustomerOrder } = await import('../customer-order.service.js')

      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })

      const input = {
        customerId: '', // empty string — should fail Zod validation
        lineItems: [
          {
            lineType: 'part' as const,
            partId: 'p1',
            description: 'Bearing 6205',
            quantity: 1,
            unitPriceNet: 1000,
            vatRateId: 'vat-standard',
          },
        ],
      }

      await expect(createCustomerOrder(input)).rejects.toThrow()
    })

    // ---------------------------------------------------------------------------
    // Reject empty line items
    // ---------------------------------------------------------------------------
    it('should reject order creation when no line items provided', async () => {
      const { createCustomerOrder } = await import('../customer-order.service.js')

      const input = {
        customerId: 'cust-abc-123',
        lineItems: [],
      }

      await expect(createCustomerOrder(input)).rejects.toThrow()
    })

    // ---------------------------------------------------------------------------
    // Reject deposit > 0 without paymentMethod
    // ---------------------------------------------------------------------------
    it('should reject order creation when depositAmount > 0 but no paymentMethod', async () => {
      const { createCustomerOrder } = await import('../customer-order.service.js')

      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })

      const input = {
        customerId: 'cust-abc-123',
        lineItems: [
          {
            lineType: 'part' as const,
            partId: 'p1',
            description: 'Bearing 6205',
            quantity: 1,
            unitPriceNet: 1000,
            vatRateId: 'vat-standard',
          },
        ],
        depositAmount: 500,
        // paymentMethod intentionally omitted
      }

      await expect(createCustomerOrder(input)).rejects.toThrow()
    })

    // ---------------------------------------------------------------------------
    // Sequential order numbers (CO-0001, CO-0002)
    // ---------------------------------------------------------------------------
    it('should return sequential order numbers', async () => {
      const { createCustomerOrder } = await import('../customer-order.service.js')

      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })

      const baseInput = {
        customerId: 'cust-abc-123',
        lineItems: [
          {
            lineType: 'part' as const,
            partId: 'p1',
            description: 'Bearing 6205',
            quantity: 1,
            unitPriceNet: 1000,
            vatRateId: 'vat-standard',
          },
        ],
      }

      const result1 = await createCustomerOrder(baseInput)
      expect(result1.order.orderNumber).toBe('CO-0001')

      const result2 = await createCustomerOrder({ ...baseInput, customerId: 'cust-def-456' })
      expect(result2.order.orderNumber).toBe('CO-0002')
    })
  })

  describe('listCustomerOrders', () => {
    it('should return empty array when no orders exist', async () => {
      const { listCustomerOrders } = await import('../customer-order.service.js')

      const result = await listCustomerOrders()
      expect(result.orders).toEqual([])
      expect(result.total).toBe(0)
    })

    it('should filter by status when provided', async () => {
      const { createCustomerOrder, updateCustomerOrderStatus } = await import('../customer-order.service.js')

      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })

      // Create two orders
      const order1 = await createCustomerOrder({
        customerId: 'cust-abc-123',
        lineItems: [{ lineType: 'part' as const, partId: 'p1', description: 'Part A', quantity: 1, unitPriceNet: 1000, vatRateId: 'vat-standard' }],
      })

      await createCustomerOrder({
        customerId: 'cust-def-456',
        lineItems: [{ lineType: 'part' as const, partId: 'p2', description: 'Part B', quantity: 1, unitPriceNet: 2000, vatRateId: 'vat-standard' }],
      })

      // Transition first order to 'ordered'
      await updateCustomerOrderStatus(order1.order.id, 'ordered')

      const pendingResult = await listCustomerOrders({ status: 'pending' })
      expect(pendingResult.orders).toHaveLength(1)
      expect(pendingResult.orders[0].status).toBe('pending')

      const orderedResult = await listCustomerOrders({ status: 'ordered' })
      expect(orderedResult.orders).toHaveLength(1)
      expect(orderedResult.orders[0].id).toBe(order1.order.id)
    })
  })

  describe('findCustomerOrderById', () => {
    it('should return order with line items and deposit total', async () => {
      const { createCustomerOrder, findCustomerOrderById } = await import('../customer-order.service.js')

      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })

      const result = await createCustomerOrder({
        customerId: 'cust-abc-123',
        lineItems: [
          { lineType: 'part' as const, partId: 'p1', description: 'Part A', quantity: 2, unitPriceNet: 1000, vatRateId: 'vat-standard' },
        ],
        depositAmount: 500,
        paymentMethod: 'cash' as const,
      })

      const orderDetail = await findCustomerOrderById(result.order.id)
      expect(orderDetail).toBeDefined()
      expect(orderDetail!.order.id).toBe(result.order.id)
      expect(orderDetail!.lineItems).toHaveLength(1)
      // Deposit total derived from allocations
      expect(orderDetail!.depositPaid).toBe(500)
    })

    it('should return undefined for non-existent order', async () => {
      const { findCustomerOrderById } = await import('../customer-order.service.js')

      const result = await findCustomerOrderById('nonexistent-id')
      expect(result).toBeUndefined()
    })
  })
})

import crypto from 'crypto'
import { db, sqliteDb } from '@/db/index.js'
import type Database from 'better-sqlite3'
import { customerOrders, customerOrderLineItems, payments, paymentAllocations, sequences, vatRates, bicycles } from '@/db/schema.js'
import { eq, asc, sql, sum, count as drizzleCount } from 'drizzle-orm'
import { createCustomerOrderInputSchema } from '@pi-skeleton/shared/validations/customer-order'
import type { CreateCustomerOrderInput, CustomerOrderStatus } from '@pi-skeleton/shared/validations/customer-order'
import { computeLineTotals } from '@shared/lib/pricing.js'

// ============================================================================
// Types
// ============================================================================

/** Result returned after a successful customer order creation */
export interface CustomerOrderResult {
  /** The created order header */
  order: typeof customerOrders.$inferSelect
  /** All line items for this order */
  lineItems: typeof customerOrderLineItems.$inferSelect[]
  /** Payment record (only present when deposit was collected) */
  payment?: typeof payments.$inferSelect
  /** Payment allocation linking deposit to the order (only present when deposit > 0) */
  allocation?: typeof paymentAllocations.$inferSelect
}

/** Full order detail with line items and derived deposit total */
export interface CustomerOrderDetail {
  order: typeof customerOrders.$inferSelect
  lineItems: typeof customerOrderLineItems.$inferSelect[]
  /** Derived from SUM(allocatedAmount) WHERE targetType='customer_order' AND targetId=orderId */
  depositPaid: number
}

/** List result with pagination support */
export interface CustomerOrderListResult {
  orders: Array<typeof customerOrders.$inferSelect & { lineItemCount: number }>
  total: number
}

// ============================================================================
// Custom Errors
// ============================================================================

/** Error thrown when deposit is attempted on an order containing leased bicycles */
export class LeasedBicycleDepositError extends Error {
  constructor() {
    super('Deposit collection not allowed for orders containing leased bicycles')
    this.name = 'LeasedBicycleDepositError'
  }
}

// ============================================================================
// Sequence helper — atomic increment for document numbering
// ============================================================================

/**
 * Get the next sequential value for a document number sequence.
 * Atomically increments the counter and returns the new value.
 */
async function getNextSequenceValue(name: string): Promise<number> {
  const updateResult = await db
    .update(sequences)
    .set({ currentValue: sql`${sequences.currentValue} + 1` })
    .where(eq(sequences.name, name))

  if (updateResult.changes === 0) {
    await db.insert(sequences).values({ name, currentValue: 1 })
    return 1
  }

  const [row] = await db
    .select({ currentValue: sequences.currentValue })
    .from(sequences)
    .where(eq(sequences.name, name))

  return row!.currentValue
}

// ============================================================================
// Validation — leased bicycle deposit check
// ============================================================================

/**
 * Check if any bicycle line items in the order reference a leased bicycle.
 * Throws LeasedBicycleDepositError if a lease is found and deposit > 0.
 */
async function validateNoLeasedBicyclesWithDeposit(
  lineItems: CreateCustomerOrderInput['lineItems'],
  depositAmount: number
): Promise<void> {
  if (depositAmount <= 0) return

  // Find all bicycle IDs from bicycle-type line items
  const bicycleIds = lineItems
    .filter(item => item.lineType === 'bicycle' && item.bicycleId)
    .map(item => item.bicycleId!)

  if (bicycleIds.length === 0) return

  // Check if any of these bicycles are leased
  const leasedBikes = await db
    .select({ id: bicycles.id, isLease: bicycles.isLease })
    .from(bicycles)
    .where(sql`${bicycles.id} IN (${sql.join(bicycleIds)}) AND ${bicycles.isLease} = 1`)

  if (leasedBikes.length > 0) {
    throw new LeasedBicycleDepositError()
  }
}

// ============================================================================
// Public API
// ============================================================================

/**
 * Create a customer order atomically in a single database transaction.
 *
 * Flow: validate input → check leased bicycles (if deposit) → get sequence number
 *       → compute line totals → insert order header → insert line items
 *       → optionally create payment + allocation for deposit
 * All-or-nothing: any failure rolls back everything.
 */
export async function createCustomerOrder(rawInput: unknown): Promise<CustomerOrderResult> {
  // Validate input via Zod schema
  const parsed = createCustomerOrderInputSchema.safeParse(rawInput)
  if (!parsed.success) {
    throw new Error(`Invalid order input: ${parsed.error.message}`)
  }

  const input = parsed.data as CreateCustomerOrderInput
  const depositAmount = input.depositAmount ?? 0

  // ---------------------------------------------------------------------------
  // Step 1: Validate leased bicycle constraint (only when deposit > 0)
  // ---------------------------------------------------------------------------
  await validateNoLeasedBicyclesWithDeposit(input.lineItems, depositAmount)

  // ---------------------------------------------------------------------------
  // Step 2: Get order number from sequence table (atomic increment)
  // ---------------------------------------------------------------------------
  const orderNumberSeq = await getNextSequenceValue('customer_order')
  const orderNumber = `CO-${String(orderNumberSeq).padStart(4, '0')}`

  // ---------------------------------------------------------------------------
  // Step 3: Fetch VAT rates needed for line item calculations
  // ---------------------------------------------------------------------------
  const allVatRates = await db.select({ id: vatRates.id, rate: vatRates.rate }).from(vatRates)
  const vatRatesMap = new Map<string, number>()
  for (const row of allVatRates) {
    vatRatesMap.set(row.id, Number(row.rate))
  }

  // ---------------------------------------------------------------------------
  // Step 4: Compute line item totals using shared pricing lib
  // ---------------------------------------------------------------------------
  const lineItemsData = input.lineItems.map((item) => {
    const vatRateBps = vatRatesMap.get(item.vatRateId) ?? 0
    const totals = computeLineTotals(
      item.unitPriceNet,
      item.quantity,
      item.discountPercent ?? null,
      vatRateBps
    )

    return {
      lineType: item.lineType,
      partId: item.partId ?? null,
      laborServiceId: item.laborServiceId ?? null,
      description: item.description,
      quantity: item.quantity,
      unitPriceNet: item.unitPriceNet,
      vatRateId: item.vatRateId,
      discountPercent: item.discountPercent ?? null,
      lineTotalNet: totals.net,
      lineTotalVat: totals.vat,
      lineTotalGross: totals.gross,
      // Bicycle-specific fields
      bicycleId: (item as any).bicycleId ?? null,
      bicycleBrand: (item as any).bicycleBrand ?? null,
      bicycleModel: (item as any).bicycleModel ?? null,
      bicycleYear: (item as any).bicycleYear ?? null,
      bicycleColor: (item as any).bicycleColor ?? null,
      bicycleFrameSize: (item as any).bicycleFrameSize ?? null,
    }
  })

  const totalPriceNet = lineItemsData.reduce((sumVal, item) => sumVal + item.lineTotalNet, 0)

  // ---------------------------------------------------------------------------
  // Step 5: Execute single transaction — all inserts or nothing
  // ---------------------------------------------------------------------------
  const orderId = crypto.randomUUID()
  let paymentId: string | undefined
  let allocationId: string | undefined

  if (depositAmount > 0 && input.paymentMethod) {
    paymentId = crypto.randomUUID()
    allocationId = crypto.randomUUID()
  }

  const client = sqliteDb as Database.Database
  const run = (sqlStr: string, params?: unknown[]) => {
    return client.prepare(sqlStr).run(...(params ?? []))
  }

  try {
    // Begin transaction
    run('BEGIN TRANSACTION')

    const now = Date.now()

    // Insert order header
    run(
      'INSERT INTO customer_orders (id, order_number, customer_id, status, total_price_net, expected_delivery_date, internal_notes, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)',
      [
        orderId,
        orderNumber,
        input.customerId,
        'pending',
        totalPriceNet,
        input.expectedDeliveryDate ?? null,
        input.internalNotes ?? null,
        now,
      ]
    )

    // Insert line items
    for (const item of lineItemsData) {
      const lineItemId = crypto.randomUUID()
      run(
        'INSERT INTO customer_order_line_items (id, customer_order_id, line_type, part_id, labor_service_id, description, quantity, unit_price_net, vat_rate_id, discount_percent, line_total_net, line_total_vat, line_total_gross, bicycle_id, bicycle_brand, bicycle_model, bicycle_year, bicycle_color, bicycle_frame_size, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
        [
          lineItemId,
          orderId,
          item.lineType,
          item.partId,
          item.laborServiceId,
          item.description,
          item.quantity,
          item.unitPriceNet,
          item.vatRateId,
          item.discountPercent,
          item.lineTotalNet,
          item.lineTotalVat,
          item.lineTotalGross,
          item.bicycleId,
          item.bicycleBrand,
          item.bicycleModel,
          item.bicycleYear,
          item.bicycleColor,
          item.bicycleFrameSize,
          now,
        ]
      )
    }

    // If deposit > 0: create payment + allocation records
    if (depositAmount > 0 && input.paymentMethod) {
      // Insert payment record
      run(
        'INSERT INTO payments (id, method, amount, created_at) VALUES (?, ?, ?, ?)',
        [paymentId!, input.paymentMethod, depositAmount, now]
      )

      // Insert payment allocation (payment → customer_order)
      run(
        'INSERT INTO payment_allocations (id, payment_id, target_type, target_id, allocated_amount) VALUES (?, ?, ?, ?, ?)',
        [allocationId!, paymentId!, 'customer_order', orderId, depositAmount]
      )
    }

    // Commit transaction
    run('COMMIT')
  } catch (err) {
    try { run('ROLLBACK') }
    catch {}
    throw err
  }

  // ---------------------------------------------------------------------------
  // Step 6: Fetch and return created entities
  // ---------------------------------------------------------------------------
  const [createdOrder] = await db.select().from(customerOrders).where(eq(customerOrders.id, orderId))
  const lineItemRows = await db.select()
    .from(customerOrderLineItems)
    .where(eq(customerOrderLineItems.orderId, orderId))
    .orderBy(asc(customerOrderLineItems.createdAt))

  let payment: typeof payments.$inferSelect | undefined
  let allocation: typeof paymentAllocations.$inferSelect | undefined

  if (paymentId) {
    const [p] = await db.select().from(payments).where(eq(payments.id, paymentId!))
    payment = p
  }

  if (allocationId) {
    const [a] = await db.select().from(paymentAllocations).where(eq(paymentAllocations.id, allocationId!))
    allocation = a
  }

  return {
    order: createdOrder!,
    lineItems: lineItemRows,
    payment,
    allocation,
  }
}

/**
 * List customer orders with optional status filter.
 */
export async function listCustomerOrders(options?: {
  status?: CustomerOrderStatus
}): Promise<CustomerOrderListResult> {
  const baseQuery = db.select({
    id: customerOrders.id,
    orderNumber: customerOrders.orderNumber,
    customerId: customerOrders.customerId,
    status: customerOrders.status,
    totalPriceNet: customerOrders.totalPriceNet,
    expectedDeliveryDate: customerOrders.expectedDeliveryDate,
    internalNotes: customerOrders.internalNotes,
    createdAt: customerOrders.createdAt,
  }).from(customerOrders)

  if (options?.status) {
    baseQuery.where(eq(customerOrders.status, options.status))
  }

  const orders = await baseQuery.orderBy(asc(customerOrders.createdAt))

  // Get total count for pagination info
  let totalCountQuery = db.select({ count: drizzleCount() }).from(customerOrders)
  if (options?.status) {
    totalCountQuery = totalCountQuery.where(eq(customerOrders.status, options.status))
  }
  const [{ count: total }] = await totalCountQuery

  return { orders, total }
}

/**
 * Find a single customer order by ID with line items and derived deposit total.
 */
export async function findCustomerOrderById(id: string): Promise<CustomerOrderDetail | undefined> {
  const [order] = await db.select().from(customerOrders).where(eq(customerOrders.id, id))
  if (!order) return undefined

  const lineItems = await db.select()
    .from(customerOrderLineItems)
    .where(eq(customerOrderLineItems.orderId, id))
    .orderBy(asc(customerOrderLineItems.createdAt))

  // Derive deposit paid from payment allocations
  const [{ depositPaid }] = await db
    .select({ depositPaid: sql<number>`COALESCE(${sum(paymentAllocations.allocatedAmount)}, 0)` })
    .from(paymentAllocations)
    .where(
      eq(paymentAllocations.targetType, 'customer_order')
        .and(eq(paymentAllocations.targetId, id))
    )

  return {
    order,
    lineItems,
    depositPaid: Number(depositPaid),
  }
}

/**
 * Transition a customer order to a new status.
 */
export async function updateCustomerOrderStatus(
  orderId: string,
  newStatus: CustomerOrderStatus
): Promise<typeof customerOrders.$inferSelect> {
  const [updated] = await db
    .update(customerOrders)
    .set({ status: newStatus })
    .where(eq(customerOrders.id, orderId))
    .returning()

  if (!updated) {
    throw new Error(`Customer order not found: ${orderId}`)
  }

  return updated
}

