import { Hono } from 'hono'
import {
  createCustomerOrder,
  listCustomerOrders,
  findCustomerOrderById,
  updateCustomerOrderStatus,
  LeasedBicycleDepositError,
} from '../services/customer-order.service.js'

const ordersRoutes = new Hono()

// ============================================================================
// POST /api/orders — Create a customer order with optional deposit
// ============================================================================

interface ErrorResponse {
  error: string
  code?: string
}

ordersRoutes.post('/', async (c) => {
  try {
    const rawInput = await c.req.json()

    const result = await createCustomerOrder(rawInput)

    return c.json(
      {
        order: Object.fromEntries(Object.entries(result.order)),
        lineItems: result.lineItems.map(item => Object.fromEntries(Object.entries(item))),
        payment: result.payment ? Object.fromEntries(Object.entries(result.payment)) : undefined,
        allocation: result.allocation ? Object.fromEntries(Object.entries(result.allocation)) : undefined,
      },
      201
    )
  } catch (err) {
    if (err instanceof LeasedBicycleDepositError) {
      return c.json(
        { error: err.message, code: 'LEASED_BICYCLE_DEPOSIT' } as ErrorResponse,
        409
      )
    }

    if (err instanceof Error && err.message.startsWith('Invalid order input')) {
      return c.json(
        { error: err.message, code: 'VALIDATION_ERROR' } as ErrorResponse,
        400
      )
    }

    console.error('[POST /api/orders] Unexpected error:', err)
    return c.json(
      { error: 'Internal server error', code: 'INTERNAL_ERROR' },
      500
    )
  }
})

// ============================================================================
// GET /api/orders — List customer orders with optional status filter
// ============================================================================

interface OrdersListResponse {
  orders: Record<string, unknown>[]
  total: number
}

ordersRoutes.get('/', async (c) => {
  const status = c.req.query('status') as 'pending' | 'ordered' | 'ready' | 'fulfilled' | 'cancelled' | undefined

  const result = await listCustomerOrders(status ? { status } : undefined)

  return c.json({
    orders: result.orders.map(order => Object.fromEntries(Object.entries(order))),
    total: result.total,
  } as OrdersListResponse)
})

// ============================================================================
// GET /api/orders/:id — Get a single order with full details
// ============================================================================

interface OrderDetailResponse {
  order: Record<string, unknown>
  lineItems: Record<string, unknown>[]
  depositPaid: number
}

ordersRoutes.get('/:id', async (c) => {
  const id = c.req.param('id')

  const detail = await findCustomerOrderById(id)
  if (!detail) {
    return c.json({ error: 'Order not found', code: 'NOT_FOUND' }, 404)
  }

  return c.json({
    order: Object.fromEntries(Object.entries(detail.order)),
    lineItems: detail.lineItems.map(item => Object.fromEntries(Object.entries(item))),
    depositPaid: detail.depositPaid,
  } as OrderDetailResponse)
})

// ============================================================================
// PATCH /api/orders/:id/status — Transition order status
// ============================================================================

ordersRoutes.patch('/:id/status', async (c) => {
  const id = c.req.param('id')
  const body = await c.req.json()
  const newStatus = body.status as 'pending' | 'ordered' | 'ready' | 'fulfilled' | 'cancelled'

  if (!newStatus || !['pending', 'ordered', 'ready', 'fulfilled', 'cancelled'].includes(newStatus)) {
    return c.json(
      { error: 'Invalid status', code: 'VALIDATION_ERROR' } as ErrorResponse,
      400
    )
  }

  try {
    const updated = await updateCustomerOrderStatus(id, newStatus)

    return c.json({
      order: Object.fromEntries(Object.entries(updated)),
    })
  } catch (err) {
    if (err instanceof Error && err.message.includes('not found')) {
      return c.json(
        { error: 'Order not found', code: 'NOT_FOUND' },
        404
      )
    }

    console.error('[PATCH /api/orders/:id/status] Unexpected error:', err)
    return c.json(
      { error: 'Internal server error', code: 'INTERNAL_ERROR' },
      500
    )
  }
})

export default ordersRoutes

import { describe, it, expect, beforeEach } from 'vitest'
import app from '@/app.js'
import { db } from '@/db/index.js'
import { customerOrders, customerOrderLineItems, payments, paymentAllocations, sequences, vatRates, bicycles } from '@/db/schema.js'
import { eq } from 'drizzle-orm'

describe('Customer Orders Routes — Integration Tests', () => {
  async function resetTables() {
    await db.delete(paymentAllocations)
    await db.delete(payments)
    await db.delete(customerOrderLineItems)
    await db.delete(customerOrders)
    await db.delete(vatRates)
    try { await db.delete(bicycles) } catch {}
    try { await db.delete(sequences).where(eq(sequences.name, 'customer_order')) } catch {}
  }

  beforeEach(async () => {
    await resetTables()
  })

  // ---------------------------------------------------------------------------
  // POST /api/orders — Create a customer order
  // ---------------------------------------------------------------------------
  describe('POST /api/orders', () => {
    it('should create a customer order without deposit (tracer bullet)', async () => {
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })

      const body = {
        customerId: 'cust-abc-123',
        lineItems: [
          {
            lineType: 'part',
            partId: 'p1',
            description: 'Bearing 6205',
            quantity: 2,
            unitPriceNet: 1000,
            vatRateId: 'vat-standard',
          },
        ],
      }

      const res = await app.request('/api/orders', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })

      expect(res.status).toBe(201)

      const json = await res.json() as Record<string, unknown>
      expect(json.order).toBeDefined()
      expect((json.order as Record<string, unknown>).customerId).toBe('cust-abc-123')
      expect((json.order as Record<string, unknown>).status).toBe('pending')
      expect((json.order as Record<string, unknown>).orderNumber).toMatch(/^CO-\d{4}$/)
      expect((json.order as Record<string, unknown>).totalPriceNet).toBe(2000)

      // No payment when no deposit
      expect(json.payment).toBeUndefined()
      expect(json.allocation).toBeUndefined()

      // Line items created
      const lineItems = json.lineItems as Record<string, unknown>[]
      expect(lineItems).toHaveLength(1)
      expect(lineItems[0].lineType).toBe('part')
    })

    it('should create a customer order with deposit payment', async () => {
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })

      const body = {
        customerId: 'cust-abc-123',
        lineItems: [
          {
            lineType: 'part',
            partId: 'p1',
            description: 'Bearing 6205',
            quantity: 1,
            unitPriceNet: 1000,
            vatRateId: 'vat-standard',
          },
        ],
        depositAmount: 500,
        paymentMethod: 'card',
      }

      const res = await app.request('/api/orders', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })

      expect(res.status).toBe(201)

      const json = await res.json() as Record<string, unknown>
      // Payment record created
      expect(json.payment).toBeDefined()
      expect((json.payment as Record<string, unknown>).amount).toBe(500)
      expect((json.payment as Record<string, unknown>).method).toBe('card')

      // Allocation links payment to order
      expect(json.allocation).toBeDefined()
      const allocation = json.allocation as Record<string, unknown>
      expect(allocation.targetType).toBe('customer_order')
      expect(allocation.allocatedAmount).toBe(500)
    })

    it('should reject deposit when leased bicycle present (409)', async () => {
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })
      await db.insert(bicycles).values({
        id: 'bike-lease-1',
        source: 'inventory' as const,
        brand: 'Trek',
        model: 'Domane',
        isLease: true,
        status: 'inventory' as const,
      })

      const body = {
        customerId: 'cust-abc-123',
        lineItems: [
          {
            lineType: 'bicycle',
            bicycleId: 'bike-lease-1',
            description: 'Trek Domane (leased)',
            quantity: 1,
            unitPriceNet: 50000,
            vatRateId: 'vat-standard',
          },
        ],
        depositAmount: 2500,
        paymentMethod: 'cash',
      }

      const res = await app.request('/api/orders', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })

      expect(res.status).toBe(409)
      const json = await res.json() as Record<string, unknown>
      expect(json.code).toBe('LEASED_BICYCLE_DEPOSIT')
    })

    it('should reject missing customerId (400)', async () => {
      const body = {
        customerId: '',
        lineItems: [
          { lineType: 'part', partId: 'p1', description: 'Test', quantity: 1, unitPriceNet: 1000, vatRateId: 'vat-std' },
        ],
      }

      const res = await app.request('/api/orders', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })

      expect(res.status).toBe(400)
    })

    it('should reject empty line items (400)', async () => {
      const body = { customerId: 'cust-abc', lineItems: [] }

      const res = await app.request('/api/orders', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })

      expect(res.status).toBe(400)
    })

    it('should reject deposit without paymentMethod (400)', async () => {
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })

      const body = {
        customerId: 'cust-abc',
        lineItems: [{ lineType: 'part', partId: 'p1', description: 'Test', quantity: 1, unitPriceNet: 1000, vatRateId: 'vat-standard' }],
        depositAmount: 500,
      }

      const res = await app.request('/api/orders', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })

      expect(res.status).toBe(400)
    })
  })

  // ---------------------------------------------------------------------------
  // GET /api/orders — List customer orders
  // ---------------------------------------------------------------------------
  describe('GET /api/orders', () => {
    it('should return empty list when no orders exist', async () => {
      const res = await app.request('/api/orders')

      expect(res.status).toBe(200)
      const json = await res.json() as Record<string, unknown>
      expect(json.orders).toEqual([])
      expect(json.total).toBe(0)
    })

    it('should filter by status', async () => {
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })

      // Create two orders via direct DB insert (simpler for this test)
      const orderId1 = crypto.randomUUID()
      const orderId2 = crypto.randomUUID()
      await db.insert(customerOrders).values([
        { id: orderId1, orderNumber: 'CO-0001', customerId: 'cust-a', status: 'pending', totalPriceNet: 1000, createdAt: Date.now() },
        { id: orderId2, orderNumber: 'CO-0002', customerId: 'cust-b', status: 'ordered', totalPriceNet: 2000, createdAt: Date.now() },
      ])

      const res = await app.request('/api/orders?status=pending')

      expect(res.status).toBe(200)
      const json = await res.json() as Record<string, unknown>
      expect(json.orders).toHaveLength(1)
      expect((json.orders[0] as Record<string, unknown>).id).toBe(orderId1)
    })
  })

  // ---------------------------------------------------------------------------
  // GET /api/orders/:id — Get order detail
  // ---------------------------------------------------------------------------
  describe('GET /api/orders/:id', () => {
    it('should return 404 for non-existent order', async () => {
      const res = await app.request('/api/orders/nonexistent-id')

      expect(res.status).toBe(404)
    })

    it('should return order detail with depositPaid derived from allocations', async () => {
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })

      // Create order via API (with deposit)
      const body = {
        customerId: 'cust-abc',
        lineItems: [{ lineType: 'part', partId: 'p1', description: 'Part A', quantity: 2, unitPriceNet: 1000, vatRateId: 'vat-standard' }],
        depositAmount: 500,
        paymentMethod: 'cash',
      }

      const createRes = await app.request('/api/orders', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })
      const createJson = await createRes.json() as Record<string, unknown>
      const orderId = (createJson.order as Record<string, unknown>).id as string

      // Fetch detail
      const res = await app.request(`/api/orders/${orderId}`)

      expect(res.status).toBe(200)
      const json = await res.json() as Record<string, unknown>
      expect(json.depositPaid).toBe(500)
      expect((json.order as Record<string, unknown>).id).toBe(orderId)
    })
  })

  // ---------------------------------------------------------------------------
  // PATCH /api/orders/:id/status — Transition status
  // ---------------------------------------------------------------------------
  describe('PATCH /api/orders/:id/status', () => {
    it('should transition order from pending to ordered', async () => {
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })

      const body = {
        customerId: 'cust-abc',
        lineItems: [{ lineType: 'part', partId: 'p1', description: 'Part A', quantity: 1, unitPriceNet: 1000, vatRateId: 'vat-standard' }],
      }

      const createRes = await app.request('/api/orders', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })
      const createJson = await createRes.json() as Record<string, unknown>
      const orderId = (createJson.order as Record<string, unknown>).id as string

      // Transition to ordered
      const res = await app.request(`/api/orders/${orderId}/status`, {
        method: 'PATCH',
        body: JSON.stringify({ status: 'ordered' }),
        headers: { 'Content-Type': 'application/json' },
      })

      expect(res.status).toBe(200)
      const json = await res.json() as Record<string, unknown>
      expect((json.order as Record<string, unknown>).status).toBe('ordered')
    })

    it('should return 404 for non-existent order', async () => {
      const res = await app.request('/api/orders/nonexistent-id/status', {
        method: 'PATCH',
        body: JSON.stringify({ status: 'ordered' }),
        headers: { 'Content-Type': 'application/json' },
      })

      expect(res.status).toBe(404)
    })

    it('should reject invalid status (400)', async () => {
      const res = await app.request('/api/orders/some-id/status', {
        method: 'PATCH',
        body: JSON.stringify({ status: 'invalid_status' }),
        headers: { 'Content-Type': 'application/json' },
      })

      expect(res.status).toBe(400)
    })
  })
})

