/**
 * Orders feature types — mirrors API response shapes for frontend use.
 */

// ============================================================================
// Order Status
// ============================================================================

export type CustomerOrderStatus = 'pending' | 'ordered' | 'ready' | 'fulfilled' | 'cancelled'

/** Color mapping for status badges */
export const ORDER_STATUS_COLORS: Record<CustomerOrderStatus, string> = {
  pending: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-400',
  ordered: 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400',
  ready: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400',
  fulfilled: 'bg-gray-100 text-gray-800 dark:bg-gray-900/30 dark:text-gray-400',
  cancelled: 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400',
}

/** Label for each status */
export const ORDER_STATUS_LABELS: Record<CustomerOrderStatus, string> = {
  pending: 'Pending',
  ordered: 'Ordered',
  ready: 'Ready',
  fulfilled: 'Fulfilled',
  cancelled: 'Cancelled',
}

// ============================================================================
// Line Item Type
// ============================================================================

export type OrderLineItemType = 'part' | 'labor' | 'bicycle'

/** Label for each line item type */
export const LINE_TYPE_LABELS: Record<OrderLineItemType, string> = {
  part: 'Part',
  labor: 'Labor',
  bicycle: 'Bicycle',
}

// ============================================================================
// Order Detail Shape (matches API response)
// ============================================================================

export interface CustomerOrderDetail {
  id: string
  orderNumber: string
  customerId: string | null
  status: CustomerOrderStatus
  totalPriceNet: number
  expectedDeliveryDate: number | null
  internalNotes: string | null
  createdAt: number
}

/** Compact order shape for list display */
export interface CustomerOrderListItem {
  id: string
  orderNumber: string
  customerId: string | null
  status: CustomerOrderStatus
  totalPriceNet: number
  expectedDeliveryDate: number | null
  internalNotes: string | null
  createdAt: number
}

// ============================================================================
// Order Line Item Shape
// ============================================================================

export interface CustomerOrderLineItem {
  id: string
  orderId: string
  lineType: OrderLineItemType
  partId: string | null
  laborServiceId: string | null
  description: string
  quantity: number
  unitPriceNet: number
  vatRateId: string
  discountPercent: number | null
  lineTotalNet: number
  lineTotalVat: number
  lineTotalGross: number
  bicycleId: string | null
  bicycleBrand: string | null
  bicycleModel: string | null
  bicycleYear: number | null
  bicycleColor: string | null
  bicycleFrameSize: string | null
}

// ============================================================================
// Create Order Form Data
// ============================================================================

/** A line item being added to the order form */
export interface OrderLineItemForm {
  lineType: OrderLineItemType
  partId?: string | null
  laborServiceId?: string | null
  description: string
  quantity: number
  unitPriceNet: number
  vatRateId: string
  discountPercent?: number | null
  bicycleId?: string | null
  bicycleBrand?: string | null
  bicycleModel?: string | null
  bicycleYear?: number | null
  bicycleColor?: string | null
  bicycleFrameSize?: string | null
}

/** Form data for creating a new customer order */
export interface CreateOrderFormData {
  customerId: string | null
  lineItems: OrderLineItemForm[]
  depositAmount: number | null
  paymentMethod: 'cash' | 'card' | null
  expectedDeliveryDate?: string | null
}

/** Default empty form state */
export const createEmptyOrderForm = (): CreateOrderFormData => ({
  customerId: null,
  lineItems: [],
  depositAmount: null,
  paymentMethod: null,
  expectedDeliveryDate: null,
})

// ============================================================================
// Customer Shape (for selection in forms)
// ============================================================================

export interface OrderCustomer {
  id: string
  displayName: string
  type: 'private' | 'company'
}

/**
 * Orders feature API client.
 */

import type {
  CustomerOrderDetail,
  CustomerOrderListItem,
  CustomerOrderLineItem,
  CreateOrderFormData,
} from './types.js'

// ---------------------------------------------------------------------------
// Types for request/response shapes
// ---------------------------------------------------------------------------

export interface OrdersListResponse {
  orders: CustomerOrderListItem[]
  total: number
}

export interface OrderDetailApiResponse {
  order: CustomerOrderDetail
  lineItems: CustomerOrderLineItem[]
  depositPaid: number
}

interface CreateOrderInput {
  customerId: string | null
  lineItems: Array<{
    lineType: 'part' | 'labor' | 'bicycle'
    partId?: string | null
    laborServiceId?: string | null
    description: string
    quantity: number
    unitPriceNet: number
    vatRateId: string
    discountPercent?: number | null
    bicycleId?: string | null
    bicycleBrand?: string | null
    bicycleModel?: string | null
    bicycleYear?: number | null
    bicycleColor?: string | null
    bicycleFrameSize?: string | null
  }>
  depositAmount?: number | null
  paymentMethod?: 'cash' | 'card' | null
  expectedDeliveryDate?: string | null
}

// ---------------------------------------------------------------------------
// API Functions — Order CRUD
// ---------------------------------------------------------------------------

/** Get paginated order list with optional status filter. */
export async function getOrders(statusFilter?: string): Promise<OrdersListResponse> {
  const params = new URLSearchParams()
  if (statusFilter) params.set('status', statusFilter)

  const response = await fetch(`/api/orders?${params.toString()}`)

  if (!response.ok) {
    throw new Error('Failed to fetch orders list')
  }

  return response.json()
}

/** Get a single order by ID with line items and deposit info. */
export async function getOrder(id: string): Promise<OrderDetailApiResponse> {
  const response = await fetch(`/api/orders/${id}`)

  if (!response.ok) {
    throw new Error('Failed to fetch order')
  }

  return response.json()
}

/** Create a new customer order with optional deposit. */
export async function createOrder(input: CreateOrderInput): Promise<{
  order: CustomerOrderDetail
  lineItems: CustomerOrderLineItem[]
  payment?: Record<string, unknown> | null
  allocation?: Record<string, unknown> | null
}> {
  const response = await fetch('/api/orders', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to create order' }))
    throw new Error(error.error || 'Failed to create order')
  }

  return response.json()
}

/** Update the status of a customer order. */
export async function updateOrderStatus(
  id: string,
  status: 'pending' | 'ordered' | 'ready' | 'fulfilled' | 'cancelled'
): Promise<CustomerOrderDetail> {
  const response = await fetch(`/api/orders/${id}/status`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ status }),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to update order status' }))
    throw new Error(error.error || 'Failed to update order status')
  }

  const json = await response.json()
  return json.order as CustomerOrderDetail
}

/**
 * Orders Page — List view with status filter tabs and "New Order" button.
 */

import { useCallback, useState } from 'react'
import toast from 'react-hot-toast'
import { useNavigate } from 'react-router-dom'
import { CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { formatCentsToEuro } from '@/shared/lib/utils.js'
import { getOrders, type OrdersListResponse } from '../api.js'
import { ORDER_STATUS_LABELS, ORDER_STATUS_COLORS, type CustomerOrderStatus, type CustomerOrderListItem } from '../types.js'
import { CreateOrderFormDialog } from './CreateOrderForm.js'

// ---------------------------------------------------------------------------
// Component — Status Badge
// ---------------------------------------------------------------------------

function StatusBadge({ status }: { status: CustomerOrderStatus }) {
  return (
    <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${ORDER_STATUS_COLORS[status]}`}>
      {ORDER_STATUS_LABELS[status]}
    </span>
  )
}

// ---------------------------------------------------------------------------
// Component — Customer Name Helper
// ---------------------------------------------------------------------------

function getCustomerLabel(customerId: string | null): string {
  if (!customerId) return 'Unknown'
  return `Customer ${customerId.slice(0, 8)}…`
}

// ---------------------------------------------------------------------------
// Component — Date Formatter
// ---------------------------------------------------------------------------

function formatDate(epochMs: number): string {
  return new Date(epochMs).toLocaleDateString('en-IE', {
    year: 'numeric',
    month: 'short',
    day: '2-digit',
  })
}

// ---------------------------------------------------------------------------
// Status filter tabs configuration
// ---------------------------------------------------------------------------

const STATUS_TABS: Array<{ value: CustomerOrderStatus | ''; label: string }> = [
  { value: '', label: 'All' },
  { value: 'pending', label: 'Pending' },
  { value: 'ordered', label: 'Ordered' },
  { value: 'ready', label: 'Ready' },
  { value: 'fulfilled', label: 'Fulfilled' },
  { value: 'cancelled', label: 'Cancelled' },
]

// ---------------------------------------------------------------------------
// Component — Orders Page
// ---------------------------------------------------------------------------

export function OrdersPage() {
  const navigate = useNavigate()
  const [orders, setOrders] = useState<CustomerOrderListItem[]>([])
  const [total, setTotal] = useState(0)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [statusFilter, setStatusFilter] = useState<CustomerOrderStatus | ''>('')

  // Dialog state for creating new orders
  const [showNewDialog, setShowNewDialog] = useState(false)

  // Fetch orders list
  const fetchOrders = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const data: OrdersListResponse = await getOrders(statusFilter || undefined)
      setOrders(data.orders)
      setTotal(data.total)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load orders')
    } finally {
      setLoading(false)
    }
  }, [statusFilter])

  // Initial fetch and re-fetch on filter change
  useState(() => {
    fetchOrders()
  })

  // Handle "New Order" button click -> opens modal dialog
  const handleNewOrder = () => {
    setShowNewDialog(true)
  }

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <CardHeader className="pb-2 px-6 pt-4">
        <div className="flex items-center justify-between">
          <CardTitle className="text-xl">Customer Orders</CardTitle>
          <Button onClick={handleNewOrder}>New Order</Button>
        </div>
      </CardHeader>

      {/* Content */}
      <CardContent className="px-6 pb-6 flex-1 overflow-auto">
        {error && (
          <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded text-sm text-red-700 dark:bg-red-900/20 dark:border-red-800 dark:text-red-400">
            <p className="font-medium">Error loading orders</p>
            <p>{error}</p>
          </div>
        )}

        {loading ? (
          <div className="flex items-center justify-center py-16 text-muted-foreground">
            Loading orders…
          </div>
        ) : orders.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 text-muted-foreground gap-2">
            <p className="text-lg font-medium">No orders yet</p>
            <p className="text-sm">Create your first customer order to get started.</p>
            <Button onClick={handleNewOrder} className="mt-2">
              New Order
            </Button>
          </div>
        ) : (
          <>
            {/* Summary + Status filter tabs */}
            <div className="mb-4 flex items-center justify-between">
              <span className="text-sm text-muted-foreground">{orders.length} of {total} order(s)</span>

              {/* Status filter tabs */}
              <div className="flex gap-1 bg-muted/50 rounded-lg p-1">
                {STATUS_TABS.map((tab) => (
                  <button
                    key={tab.value || 'all'}
                    onClick={() => setStatusFilter(tab.value)}
                    className={`px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${
                      statusFilter === tab.value
                        ? 'bg-background text-foreground shadow-sm'
                        : 'text-muted-foreground hover:text-foreground'
                    }`}
                  >
                    {tab.label}
                  </button>
                ))}
              </div>
            </div>

            {/* Orders table */}
            <div className="border rounded-lg overflow-hidden">
              <table className="w-full text-sm">
                <thead>
                  <tr className="bg-muted/50 border-b">
                    <th className="text-left px-4 py-2 font-medium text-muted-foreground">Order #</th>
                    <th className="text-center px-4 py-2 font-medium text-muted-foreground">Status</th>
                    <th className="text-left px-4 py-2 font-medium text-muted-foreground">Customer</th>
                    <th className="text-right px-4 py-2 font-medium text-muted-foreground">Total (net)</th>
                    <th className="text-left px-4 py-2 font-medium text-muted-foreground">Created</th>
                  </tr>
                </thead>
                <tbody>
                  {orders.map((order) => (
                    <tr key={order.id} className="border-b last:border-b-0 hover:bg-muted/30 transition-colors cursor-pointer" onClick={() => navigate(`/orders/${order.id}`)}>
                      <td className="px-4 py-2 font-mono text-xs">{order.orderNumber}</td>
                      <td className="px-4 py-2 text-center">
                        <StatusBadge status={order.status} />
                      </td>
                      <td className="px-4 py-2">{getCustomerLabel(order.customerId)}</td>
                      <td className="px-4 py-2 text-right font-mono tabular-nums">{formatCentsToEuro(order.totalPriceNet)}</td>
                      <td className="px-4 py-2 whitespace-nowrap">{formatDate(order.createdAt)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </>
        )}

        {/* New Order Dialog Modal */}
        <CreateOrderFormDialog
          isOpen={showNewDialog}
          onClose={() => setShowNewDialog(false)}
          onSuccess={(orderId) => {
            toast.success('Order created successfully')
            fetchOrders()
            navigate(`/orders/${orderId}`)
          }}
        />
      </CardContent>
    </div>
  )
}

