/**
 * Create Quote Form — Dialog for creating a new draft quote.
 */

import { useCallback, useEffect, useRef, useState } from 'react'
import { User, Building2 } from 'lucide-react'
import type { CreateQuoteFormData } from '../types.js'
import { createEmptyQuoteForm } from '../types.js'
import { createQuote } from '../api.js'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface QuoteCustomer {
  id: string
  displayName: string
  type: 'private' | 'company'
}

interface CreateQuoteDialogProps {
  isOpen: boolean
  onClose: () => void
  onSuccess: (quoteId: string) => void
}

// ---------------------------------------------------------------------------
// Debounce hook — minimal inline implementation (250ms)
// ---------------------------------------------------------------------------

function useDebounce<T>(value: T, delayMs: number): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value)

  useEffect(() => {
    const timer = setTimeout(() => setDebouncedValue(value), delayMs)
    return () => clearTimeout(timer)
  }, [value, delayMs])

  return debouncedValue
}

// ---------------------------------------------------------------------------
// Component — Customer Selector (autocomplete combobox)
// Matches the proven pattern from POS / RepairIntakeModal.
// ---------------------------------------------------------------------------

function CustomerSelector({
  selectedCustomerId,
  onSelect,
}: {
  selectedCustomerId: string | null
  onSelect: (customerId: string | null) => void
}) {
  const [customers, setCustomers] = useState<QuoteCustomer[]>([])
  const [query, setQuery] = useState('')
  const [isLoading, setIsLoading] = useState(false)
  const [isOpen, setIsOpen] = useState(false)
  const [highlightIndex, setHighlightIndex] = useState(-1)

  // Cached selected customer (fetched on mount if customerId is set)
  const [selectedCustomerCache, setSelectedCustomerCache] = useState<QuoteCustomer | null>(null)

  // Debounced query (250ms delay before API call)
  const debouncedQuery = useDebounce(query, 250)

  // Refs for keyboard navigation and click-outside detection
  const inputRef = useRef<HTMLInputElement>(null)
  const dropdownRef = useRef<HTMLDivElement>(null)

  // ── Fetch selected customer on mount (if customerId is set) ──────

  useEffect(() => {
    if (!selectedCustomerId) return

    let cancelled = false

    async function fetchSelectedCustomer() {
      try {
        const response = await fetch('/api/customers')
        if (response.ok) {
          const data: { customers: QuoteCustomer[] } = await response.json()
          if (!cancelled) {
            const found = data.customers?.find((c) => c.id === selectedCustomerId)
            setSelectedCustomerCache(found ?? null)
          }
        }
      } catch {
        // Silently fail
      }
    }

    fetchSelectedCustomer()
    return () => { cancelled = true }
  }, [selectedCustomerId])

  // ── Fetch customers on debounced query change ────────────────────

  useEffect(() => {
    if (!debouncedQuery || debouncedQuery.trim() === '') {
      setCustomers([])
      setIsOpen(false)
      return
    }

    let cancelled = false

    async function fetchCustomers() {
      setIsLoading(true)
      try {
        const response = await fetch(`/api/customers?search=${encodeURIComponent(debouncedQuery.trim())}`)
        if (response.ok) {
          const data: { customers: QuoteCustomer[] } = await response.json()
          if (!cancelled) {
            setCustomers((data.customers ?? []).slice(0, 20))
            setIsOpen(true)
            setHighlightIndex(-1)
          }
        } else {
          if (!cancelled) {
            setCustomers([])
            setIsOpen(false)
          }
        }
      } catch {
        if (!cancelled) {
          setCustomers([])
          setIsOpen(false)
        }
      } finally {
        if (!cancelled) {
          setIsLoading(false)
        }
      }
    }

    fetchCustomers()
    return () => { cancelled = true }
  }, [debouncedQuery])

  // ── Click-outside handler ────────────────────────────────────────

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (
        dropdownRef.current && !dropdownRef.current.contains(event.target as Node) &&
        inputRef.current && !inputRef.current.contains(event.target as Node)
      ) {
        setIsOpen(false)
      }
    }

    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [])

  // ── Select a customer ────────────────────────────────────────────

  const handleSelectCustomer = useCallback((id: string | null) => {
    onSelect(id)
    setIsOpen(false)
    if (id === null) {
      setQuery('')
      setCustomers([])
    }
  }, [onSelect])

  // ── Keyboard navigation ──────────────────────────────────────────

  const handleKeyDown = useCallback((e: React.KeyboardEvent<HTMLInputElement>) => {
    if (!isOpen || customers.length === 0) return

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault()
        setHighlightIndex((prev) => Math.min(prev + 1, customers.length - 1))
        break

      case 'ArrowUp':
        e.preventDefault()
        setHighlightIndex((prev) => Math.max(prev - 1, 0))
        break

      case 'Enter':
        e.preventDefault()
        if (highlightIndex >= 0 && highlightIndex < customers.length) {
          handleSelectCustomer(customers[highlightIndex].id)
        } else if (customers.length === 1) {
          handleSelectCustomer(customers[0].id)
        }
        break

      case 'Escape':
        e.preventDefault()
        setIsOpen(false)
        inputRef.current?.blur()
        break
    }
  }, [isOpen, customers, highlightIndex, handleSelectCustomer])

  // ── Render helpers ───────────────────────────────────────────────

  const displaySelectedCustomer = selectedCustomerCache ?? customers.find((c) => c.id === selectedCustomerId) ?? null

  return (
    <div className="space-y-2">
      {/* Label */}
      <label htmlFor="customer-search" className="text-sm font-medium text-muted-foreground">
        Customer
      </label>

      {/* Search input with dropdown */}
      <div ref={dropdownRef} className="relative">
        <Input
          id="customer-search"
          ref={inputRef}
          type="search"
          placeholder="Search customers..."
          value={query}
          onChange={(e) => {
            setQuery(e.target.value)
            setIsOpen(true)
            setHighlightIndex(-1)
          }}
          onFocus={() => {
            if (customers.length > 0) setIsOpen(true)
          }}
          onKeyDown={handleKeyDown}
          className="w-full"
        />

        {/* Dropdown */}
        {isOpen && customers.length > 0 && (
          <div className="absolute z-50 w-full mt-1 bg-popover border rounded-md shadow-lg max-h-64 overflow-y-auto">
            {isLoading && (
              <div className="px-3 py-2 text-sm text-muted-foreground">Searching...</div>
            )}

            {!isLoading && customers.map((customer, index) => (
              <button
                key={customer.id}
                type="button"
                onClick={() => handleSelectCustomer(customer.id)}
                onMouseEnter={() => setHighlightIndex(index)}
                className={`w-full text-left px-3 py-2 text-sm transition-colors ${
                  index === highlightIndex
                    ? 'bg-accent text-accent-foreground'
                    : selectedCustomerId === customer.id
                      ? 'bg-muted/50 font-medium'
                      : 'hover:bg-accent hover:text-accent-foreground'
                }`}
              >
                <div className="flex items-center gap-2">
                  {customer.type === 'company' ? (
                    <Building2 className="h-4 w-4 flex-shrink-0 text-muted-foreground" />
                  ) : (
                    <User className="h-4 w-4 flex-shrink-0 text-muted-foreground" />
                  )}
                  <div className="min-w-0">
                    <div className="font-medium truncate">{customer.displayName}</div>
                    <div className="text-xs text-muted-foreground capitalize">{customer.type}</div>
                  </div>
                </div>
              </button>
            ))}
          </div>
        )}

        {/* No results */}
        {isOpen && query.trim() !== '' && !isLoading && customers.length === 0 && (
          <div className="absolute z-50 w-full mt-1 bg-popover border rounded-md shadow-lg px-3 py-2 text-sm text-muted-foreground">
            No customers found
          </div>
        )}
      </div>

      {/* Walk-in option — always visible */}
      <button
        type="button"
        onClick={() => handleSelectCustomer(null)}
        className={`w-full justify-start text-sm px-3 py-2 rounded-md border transition-colors ${
          selectedCustomerId === null
            ? 'bg-primary text-primary-foreground border-transparent'
            : 'border-dashed border-input hover:bg-accent hover:text-accent-foreground'
        }`}
      >
        Walk-in (anonymous)
      </button>

      {/* Selected customer info */}
      {selectedCustomerId !== null && displaySelectedCustomer && (
        <div className="pt-2 border-t text-xs text-muted-foreground space-y-0.5">
          <span className="font-medium">{displaySelectedCustomer.displayName}</span>
          <span className="text-muted-foreground capitalize ml-1">({displaySelectedCustomer.type})</span>
        </div>
      )}

      {/* Walk-in selected info */}
      {selectedCustomerId === null && (
        <div className="pt-2 border-t text-xs text-muted-foreground italic">
          Anonymous quote — no customer attached
        </div>
      )}
    </div>
  )
}

// ---------------------------------------------------------------------------
// Component — Create Quote Dialog
// ---------------------------------------------------------------------------

export function CreateQuoteDialog({ isOpen, onClose, onSuccess }: CreateQuoteDialogProps) {
  const [formData, setFormData] = useState<CreateQuoteFormData>(createEmptyQuoteForm())
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState<string | null>(null)

  // Reset form when dialog opens
  useEffect(() => {
    if (isOpen) {
      setFormData(createEmptyQuoteForm())
      setError(null)
    }
  }, [isOpen])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setSubmitting(true)
    setError(null)

    try {
      const quote = await createQuote(formData)
      onSuccess(quote.id)
      onClose()
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to create quote')
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>New Quote</DialogTitle>
          <DialogDescription>
            Create a new draft quote. You can add line items after creation.
          </DialogDescription>
        </DialogHeader>

        {error && (
          <div className="rounded-md border border-red-200 bg-red-50 p-3 text-sm text-red-700 dark:bg-red-900/20 dark:border-red-800 dark:text-red-400">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          {/* Customer Selector */}
          <CustomerSelector
            selectedCustomerId={formData.customerId}
            onSelect={(customerId) => setFormData(prev => ({ ...prev, customerId }))}
          />

          {/* Notes */}
          <div className="space-y-2">
            <label htmlFor="notes" className="text-sm font-medium text-muted-foreground">
              Notes (optional)
            </label>
            <textarea
              id="notes"
              rows={3}
              value={formData.notes}
              onChange={(e) => setFormData(prev => ({ ...prev, notes: e.target.value }))}
              placeholder="Internal notes about this quote..."
              className="w-full rounded-md border border-input bg-background px-3 py-2 text-sm focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/20 resize-none"
            />
          </div>

          {/* Total Discount */}
          <div className="space-y-2">
            <label htmlFor="totalDiscount" className="text-sm font-medium text-muted-foreground flex items-center justify-between">
              <span>Total Discount (%)</span>
              <span className="text-xs text-muted-foreground font-normal">(client-side only)</span>
            </label>
            <div className="flex items-center gap-2">
              <input
                id="totalDiscount"
                type="number"
                min={0}
                max={100}
                step={0.1}
                value={formData.totalDiscountPercent ?? ''}
                onChange={(e) => {
                  const val = e.target.value === '' ? null : parseFloat(e.target.value)
                  setFormData(prev => ({ ...prev, totalDiscountPercent: val }))
                }}
                placeholder="0"
                className="w-24 rounded-md border border-input bg-background px-3 py-2 text-sm focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/20"
              />
              <span className="text-sm text-muted-foreground">%</span>
            </div>
            <p className="text-xs text-muted-foreground">Applied client-side to line item totals. Not persisted to database.</p>
          </div>

          {/* Actions */}
          <DialogFooter className="gap-2 sm:gap-0">
            <Button type="button" variant="outline" onClick={onClose} disabled={submitting}>
              Cancel
            </Button>
            <Button type="submit" disabled={submitting}>
              {submitting ? 'Creating...' : 'Create Quote'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  )
}

